    <div class="form-step" id="step2">
      <p class="form-progress">02 / 02</p>
      <div class="form-field" style="grid-template-columns:1fr;display:block;padding:20px 0;border-top:0.5px solid rgba(27,58,92,0.2);">
        <label class="form-label" style="display:block;margin-bottom:16px;">Contános tu proyecto <span class="req">*</span></label>
        <textarea class="form-textarea" id="f-desc" placeholder="Describiá brevemente el proyecto, tipo de obra, ubicación y cualquier detalle relevante..." style="min-height:140px;"></textarea>
      </div>
      <div class="form-actions">
        <button class="form-btn" onclick="goStep1()" style="color:var(--text-mid);border-color:rgba(27,58,92,0.15);">Atrás</button>
        <button class="form-btn" style="margin-left:12px;" onclick="sendForm()">Enviar consulta</button>
        <div class="form-btn-arrow" onclick="sendForm()">&#8594;</div>
      </div>
    </div>
